const test=require('node:test'),assert=require('node:assert/strict');
test('Board has exactly 10 offset rows and columns and rejects multihex overflow',async()=>{const b=await import('../board-terrain.js'),m=await import('../playground-model.js');assert.equal(b.BOARD_CELLS.length,100);assert.equal(new Set(b.BOARD_CELLS.map(c=>c.q+','+c.r)).size,100);for(let r=0;r<10;r++)assert.equal(b.BOARD_CELLS.filter(c=>c.row===r).length,10);const card={id:'test',revision:1,cells:[{q:0,r:0},{q:1,r:0}],rendition:{meshes:[]}},v=m.editBoard(m.emptyBoard('b'),'place',{card,newInstanceId:'i',q:0,r:0});assert(b.validateFootprints(v));const edge=b.BOARD_CELLS.find(c=>c.row===5&&c.col===9);assert.throws(()=>b.validateFootprints(m.editBoard(v,'move',{instanceId:'i',q:edge.q,r:edge.r})),/beyond/);});
test('Sweeping height field is deterministic and continuous at shared boundaries with level working pads',async()=>{const {rawTerrain,boardHeight}=await import('../board-terrain.js');let min=Infinity,max=-Infinity;for(let x=-400;x<=400;x+=10)for(let z=-350;z<=350;z+=10){const h=rawTerrain(x,z);assert(Number.isFinite(h));min=Math.min(min,h);max=Math.max(max,h);assert(Math.abs(h-rawTerrain(x+.001,z))<.002);}assert(max-min>45);const h=boardHeight({plans:[{center:{x:0,z:0},placements:[{x:0,z:0,radius:12}]}]});assert.equal(h(0,0),h(10,0));});
test('Arbitrary board centers drive shared paths and preserve source recipes',async()=>{const {planAssembly}=await import('../tile-adapter.js');const tiles=[{id:'a',type:'ranch',cell:0,center:{x:0,z:0},rotation:0,seed:41},{id:'b',type:'paddock',cell:99,center:{x:Math.sqrt(3)*50,z:0},rotation:0,seed:82}];const source=JSON.stringify(tiles),a=planAssembly({tiles});assert.equal(a.links.length,1);assert.equal(JSON.stringify(tiles),source);const p=a.plans[0],q=a.plans[1];assert(Math.abs(p.center.x+p.ports[0].x-q.center.x-q.ports[0].x)<1e-6);});
test('Saved cards require an actual rendition and a unique footprint',async()=>{const {createCard}=await import('../card-library.js');assert.throws(()=>createCard({name:'x',cells:[{q:0,r:0}]}),/rendition/);const card=createCard({name:'x',cells:[{q:0,r:0}],rendition:{meshes:[]},recipe:{seed:41}});assert.equal(card.units,'metres');assert.equal(card.recipe.seed,41);});

test('composition edits retain immutable geometry and history waits for a successful render',async()=>{const {editComposition,compositionHistory}=await import('../board-state.js'),{emptyBoard}=await import('../playground-model.js');const card={id:'c',revision:1,cells:[{q:0,r:0}],rendition:{meshes:[{positions:[1,2,3]}]}};const b=editComposition(emptyBoard('b'),'place',{card,newInstanceId:'i',q:0,r:0});const history=compositionHistory(b),m=editComposition(b,'move',{instanceId:'i',q:1,r:0});assert.equal(m.cards['c@1'],card);assert.equal(b.instances[0].q,0);history.commit(m);const before=history.available();const candidate=history.peek('undo');assert.equal(candidate.instances[0].q,0);assert.deepEqual(history.available(),before);history.accept('undo',candidate);assert.equal(history.available().redo,1);});
